// Renders the email from the shared template (same function as js/briefing.js). No tracking pixels.
const tpl = $('Fetch email template').first().json.data;
const SITE = $env.CIVI_SITE_URL; // e.g. https://civi.chainnes.com (n8n env var)
function briefingEmailHTML(tpl, items, o) {
  const D = { "&rsquo;": "’", "&lsquo;": "‘", "&ldquo;": "“", "&rdquo;": "”", "&amp;": "&", "&quot;": '"', "&#39;": "'", "&#8217;": "’", "&hellip;": "…", "&nbsp;": " " };
  const e = s => String(s ?? "").replace(/&(?:[a-z]+|#\d+);/g, m => D[m] ?? m).replace(/[&<>"']/g, c => ({ "&": "&amp;", "<": "&lt;", ">": "&gt;", '"': "&quot;", "'": "&#39;" }[c]));
  const col = s => { let h = 0; for (const c of String(s)) h = (h * 31 + c.charCodeAt(0)) % 360; return `hsl(${h},70%,40%)`; };
  const rows = items.filter(i => /^https:\/\//.test(i.url)).map((i, n) => `<table role="presentation" width="100%" cellpadding="0" cellspacing="0" style="border-top:1px solid #e3e9f1"><tr>
    <td valign="top" style="width:28px;padding:14px 0;font-size:18px;font-weight:bold;color:#0b6fa4">${n + 1}</td><td style="padding:14px 0">
    <span style="display:inline-block;width:18px;height:18px;line-height:18px;border-radius:9px;background:${col(i.source)};color:#fff;font-size:9px;font-weight:bold;text-align:center;vertical-align:middle">${e(String(i.source).replace(/[^A-Za-z0-9]/g, "").slice(0, 2).toUpperCase())}</span>
    <span style="font-size:12px;color:#51627a;vertical-align:middle">&nbsp;${e(i.source)}</span>
    <div style="margin-top:6px"><a href="${e(i.url)}" style="color:#0b1626;font-size:16px;font-weight:bold;text-decoration:none;line-height:1.35">${e(i.title)}</a></div>
    ${i.summary ? `<div style="font-size:13px;color:#51627a;margin-top:4px;line-height:1.45">${e(i.summary).slice(0, 260)}${i.summary_is_ai ? ' <i style="color:#a05a00">(machine-generated summary)</i>' : ""}</div>` : ""}
    <div style="margin-top:6px"><a href="${e(i.url)}" style="font-size:12px;color:#0b6fa4">Read at source &rarr;</a></div></td></tr></table>`).join("");
  const map = { PREHEADER: `${items.length} stories for ${o.scope}`, DATE: o.date, SCOPE: o.scope, ITEMS: rows, SITE: o.site, UNSUB_URL: o.unsub, SETTINGS_URL: o.site + "/#/briefing/settings" };
  return tpl.replace(/\{\{(\w+)\}\}/g, (_, k) => k === "ITEMS" ? map.ITEMS : e(map[k] ?? ""));
}

const d = $json; if (!d || !d.email || !Array.isArray(d.items) || !d.items.length) return { json: { skip: true, user_id: d && d.user_id } };
const unsub = `${SITE}/api/briefing/unsubscribe?t=${d.token}`;
const date = new Date().toLocaleDateString('en-PH', { weekday: 'long', month: 'long', day: 'numeric', year: 'numeric', timeZone: 'Asia/Manila' });
const html = briefingEmailHTML(tpl, d.items, { date, scope: d.scope, site: SITE, unsub });
const text = `Your Civi Briefing, ${date}\n\n` + d.items.map((i, n) => `${n + 1}. ${i.title} (${i.source})\n${i.url}`).join('\n\n') + `\n\nUnsubscribe: ${unsub}\nSettings: ${SITE}/#/briefing/settings\nPrivacy: privacy@chainnes.com`;
return { json: { skip: false, user_id: d.user_id, n: d.items.length, payload: {
  from: $env.BRIEFING_FROM, to: [d.email], subject: `Your Civi Briefing · ${d.items[0].title.slice(0, 60)}`, html, text,
  headers: { 'List-Unsubscribe': `<${unsub}>, <mailto:privacy@chainnes.com?subject=unsubscribe>`, 'List-Unsubscribe-Post': 'List-Unsubscribe=One-Click' } } } };

// OPTIONAL Web Push. Needs n8n env NODE_FUNCTION_ALLOW_EXTERNAL=web-push (self-hosted n8n, `npm i web-push`) and env VAPID_PUBLIC_KEY / VAPID_PRIVATE_KEY / VAPID_SUBJECT.
// Disabled by default. Sends only a short title + link to the user's own briefing; no personal data in the payload.
const webpush = require('web-push');
webpush.setVapidDetails($env.VAPID_SUBJECT || 'mailto:privacy@chainnes.com', $env.VAPID_PUBLIC_KEY, $env.VAPID_PRIVATE_KEY);
const out = [];
for (const it of $input.all()) { const s = it.json;
  try { await webpush.sendNotification({ endpoint: s.endpoint, keys: { p256dh: s.p256dh, auth: s.auth } },
      JSON.stringify({ title: `Your Civi Briefing · ${s.n} new`, body: String(s.top_title || '').slice(0, 120), url: '/#/briefing' }), { TTL: 6 * 3600 });
    out.push({ json: { user_id: s.user_id, status: 'sent' } });
  } catch (e) { out.push({ json: { user_id: s.user_id, status: e.statusCode === 410 || e.statusCode === 404 ? 'gone' : 'error', endpoint: s.endpoint } }); }
}
return out;  // TIP: delete 'gone' endpoints from push_subscriptions.
